customCSS:
.t, .history { color: #4a5057; }
.join { color: #95c561; }
.part, .quit { color: #4a5057; }
.kick, .error { color: #ee6d85; }
.notice { color: #d7a65f; }
.action { color: #a485dd; }
.mode, .nick, .topic, .server { color: #38a89d; }
.highlight { color: #a0a8cd; background-color: #25283b; border-left: 3px solid #a485dd; padding-left: 8px; }
.reply { color: #4a5057; border-left: 2px solid #7199ee; padding-left: 6px; }
.oper { color: #11121d; background-color: #d7a65f; }
.reactions { color: #7199ee; background-color: #06080a; }
.card { background-color: #06080a; border-color: #4a5057; }
.card-title { color: #7199ee; }
.card-desc { color: #4a5057; }
.daychange { color: #4a5057; border-color: #06080a; }
